PREFERENCE_FIELDS = (
    "property_change",
    "state_change",
    "comment",
    "mention",
    "issue_completed",
)


def normalize_notification_preferences(apps, schema_editor):
    """Merge duplicate preferences, audit disabled values, and fill missing users."""
    User = apps.get_model("db", "User")
    Preference = apps.get_model("db", "UserNotificationPreference")
    Audit = apps.get_model("db", "NotificationPreferenceMigrationAudit")
    database = schema_editor.connection.alias

    user_ids = list(Preference.objects.using(database).values_list("user_id", flat=True).distinct())
    for user_id in user_ids:
        rows = list(Preference.objects.using(database).filter(user_id=user_id).order_by("created_at", "id"))
        if not rows:
            continue
        merged = {field: all(getattr(row, field) for row in rows) for field in PREFERENCE_FIELDS}
        disabled = sorted(field for field, value in merged.items() if not value)
        if len(rows) > 1:
            Audit.objects.using(database).create(
                user_id=user_id,
                source_row_count=len(rows),
                merged_disabled_fields=disabled,
            )
        keeper = rows[-1]
        for field, value in merged.items():
            setattr(keeper, field, value)
        keeper.assignment = merged["property_change"]
        keeper.research_property_change = merged["property_change"]
        keeper.research_state_change = merged["state_change"]
        keeper.research_comment = merged["comment"]
        keeper.research_mention = merged["mention"]
        keeper.research_completion = merged["issue_completed"]
        keeper.save(
            using=database,
            update_fields=[
                *PREFERENCE_FIELDS,
                "assignment",
                "research_property_change",
                "research_state_change",
                "research_comment",
                "research_mention",
                "research_completion",
            ],
        )
        if len(rows) > 1:
            Preference.objects.using(database).filter(user_id=user_id).exclude(pk=keeper.pk).delete()

    existing_user_ids = set(user_ids)
    missing_preferences = [
        Preference(user_id=user.pk)
        for user in User.objects.using(database).only("id").iterator()
        if user.pk not in existing_user_ids
    ]
    Preference.objects.using(database).bulk_create(missing_preferences, batch_size=1000, ignore_conflicts=True)


def mark_existing_email_logs_legacy(apps, schema_editor):
    """Keep pre-migration mail records out of the new send queue."""
    EmailLog = apps.get_model("db", "EmailNotificationLog")
    EmailLog.objects.using(schema_editor.connection.alias).update(delivery_status="legacy")


